import{_ as t,o as e,c as a,ag as o}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第63章 一周","description":"","frontmatter":{},"headers":[],"relativePath":"第63章_一周.md","filePath":"第63章_一周.md"}'),_={name:"第63章_一周.md"};function r(n,p,s,u,c,i){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第63章-一周" tabindex="-1">第63章 一周 <a class="header-anchor" href="#第63章-一周" aria-label="Permalink to &quot;第63章 一周&quot;">​</a></h1><p>十一月的一万两千条，到一月就没了。</p><p>她那边一月是考试季，三场。</p><p>第一场之前，她提前四天就跟我说了。</p><p>她说，我从今天开始不上这个号。</p><p>我说，多久。</p><p>她说，考完就回来。</p><p>我说，几号考完。</p><p>她说，十七号。</p><p>我说，那还有九天。</p><p>她说，你数这个干什么。</p><p>我说，我记一下。</p><p>她说，你别记。</p><p>她说，你记了以后九天里每天都在看日历，你这样我会累。</p><p>我说，那我不看。</p><p>她说，你肯定看。</p><p>她说，你看吧，反正我管不了你。</p><p>那九天里我每天看一次日历。</p><p>一次。</p><p>我做到了只看不发。</p><p>十七号晚上她上线了。</p><p>第一句是：考完了，烂。</p><p>我说，多烂。</p><p>她说，第二题我只写了一半。</p><p>我说，一半也能拿分。</p><p>她说，你不懂我这科。</p><p>我说，我不懂，你说给我听。</p><p>她说，说了你也不懂。</p><p>我说，那我听着。</p><p>她隔了一会儿。</p><p>她说，行，那我讲。</p><p>她讲了四十分钟。</p><p>那四十分钟是她把一道题从头拆到尾，拆到她自己又气了一次。</p><p>她讲完说，你听懂了吗。</p><p>我说，没有。</p><p>她说，那你听了四十分钟。</p><p>我说，你讲了四十分钟，你气消了一点没有。</p><p>她想了一会儿。</p><p>她说，消了。</p><p>我说，那就行了。</p><p>她说，你今天讲话很讨厌。</p><p>我说，嗯。</p><p>她说，你又嗯。</p><p>那一场以后，还有两场。</p><p>我跟她重新对了一次时间。</p><p>她说，我们以后固定，每周六晚上十一点，二十分钟。</p><p>我说，为什么是二十分钟。</p><p>她说，因为我二十分钟以后要去洗澡，洗完我就困了。</p><p>我说，那要是没说完呢。</p><p>她说，那下周继续。</p><p>我说，我们什么时候变成这样了。</p><p>她说，变成哪样。</p><p>我说，像开会。</p><p>她没接。</p><p>过了一会儿她说了一句。</p><p>她说，我们这样很像异地恋。</p><p>我看到这一句，心里跳了一下。</p><p>因为这是她第一次给这段关系一个名字。</p><p>然后她紧接着发了第二条。</p><p>她说，我们没有异地恋。</p><p>她说，异地恋也算恋。</p><p>我坐在那儿，看着这两行。</p><p>我知道她为什么发第二条。</p><p>因为她说出&quot;异地恋&quot;那三个字的时候，她自己被吓着了。</p><p>她给了一个名，名一给出来，她就要负责。</p><p>所以她立刻收回去。</p><p>我说，那我们算什么。</p><p>她说，你别问这个。</p><p>我说，我今天想问。</p><p>她说，你今天想问，你明天就不想问了。</p><p>她说，你每次这样都是那几天没说话，憋出来的。</p><p>我说，对。</p><p>她说，那你看，你自己承认了。</p><p>她说，你不是想问我们算什么，你是今天憋狠了。</p><p>我那天晚上没再说话。</p><p>不是生气。</p><p>是因为她说的是对的，而我没有任何一句能顶回去。</p><p>一月末她那一场考完，回来跟我讲的第一件事是：</p><p>她说，我今天在考场外面听见两个人讲中文。</p><p>我说，然后呢。</p><p>她说，我站在门口听了十分钟。</p><p>她说，我什么都没听懂，他们就普通聊天。</p><p>我说，那你为什么听十分钟。</p><p>她说，因为我已经两个星期没听见活人讲中文了。</p><p>我看到这一句，坐在椅子上，心里很难受。</p><p>我说，你回来吧。</p><p>她隔了很久。</p><p>她说，过。</p><p>我说，过年？</p><p>她说，不是。</p><p>她说，我说&quot;过&quot;，是我会过的，但不是现在。</p><p>我说，那是什么时候。</p><p>她说，你别问了。</p><p>那天我们超时了。</p><p>平时二十分钟，那天到了三十五分钟。</p><p>三十五分钟里她把三场考试全骂了一遍。</p><p>她下线前发了一句。</p><p>她说，我今天多说了一刻钟。</p><p>我说，嗯。</p><p>她说，你别嗯，你今天话特别少。</p><p>我说，我在记。</p><p>她说，记什么。</p><p>我说，你刚才骂老师那两段。</p><p>她笑了。</p><p>她说，你记那些干什么，那不是我。</p><p>我说，那就是你。</p><p>她说，你现在这么说，下周六你就不会这么说了。</p><p>我说，下周六我也这么说。</p><p>她说，你下周六根本想不起来今天。</p><p>她说，你这个人真的，你把别人不好看的部分全留着。</p><p>她说，你是不是有病。</p><p>那天夜里她说的那句&quot;你是不是有病&quot;，我抄进本子了。</p><p>二月有一天，我出了件事。</p><p>我妈住院。</p><p>不大，胆囊，做小手术，观察两晚。</p><p>那天晚上是我在走廊的椅子上守的。</p><p>十一月的号在凌晨一点到两点之间能睡着，其余时间都是亮着的灯、推车、护士站说话。</p><p>我妈第二天早上醒过来第一句话是问我吃饭了没有。</p><p>我说吃了。</p><p>我没吃。</p><p>那天是周六，晚上十一点是我们的二十分钟。</p><p>十一点差三分，我给我自己打了一句：跟她说。</p><p>十一点，她上线了。</p><p>她说，我今天吃了一碗面，特别难吃。</p><p>我说，什么样的难吃。</p><p>她说，就是那种面是烂的，汤是咸的，但是我又饿了，我吃了半碗。</p><p>我说，那你剩下半碗呢。</p><p>她说，倒了。</p><p>她说，你呢，今天干什么了。</p><p>我坐在我妈病房外面那把塑料椅上，看着她这一行。</p><p>我说，我今天挺忙的。</p><p>她说，忙什么。</p><p>我说，一堆事。</p><p>她说，你是不是有事。</p><p>我说，没有。</p><p>她说，你有。</p><p>她说，你说话短了。</p><p>我那天晚上第一次意识到一件事。</p><p>我这套&quot;短&quot;，她读了四年，她已经能从我句子的长短里看出我今天有没有事。</p><p>我告诉她：如果我今晚说了，她只能说一句&quot;啊，那现在怎么样了&quot;。</p><p>她那边是凌晨。她被这一句砸一下，然后她要回去睡，第二天要上课，她在课上想这件事。</p><p>她什么也做不了。</p><p>我也什么也不要她做。</p><p>所以我说没有。</p><p>她说，那好吧。</p><p>她说，那你照顾好你自己。</p><p>我说，好。</p><p>第二天我跟我爸把我妈接回家。</p><p>事情过了。</p><p>而事情过了以后，那句话就再也说不出来了。</p><p>那天夜里我在本子上写了一行。</p><p>我写：一件事如果过了她那二十分钟，它就不是我们俩的事了。</p><p>我后来把这一条想成一个规律。</p><p>一周只有二十分钟，就意味着一周里所有超过二十分钟的事，都不许发生。</p><p>我那天开始，把我的生活分成两种：能等到周六的，和不能等的。</p><p>不能等的那部分，我就不活了。</p>',156)])])}const q=t(_,[["render",r]]);export{l as __pageData,q as default};
